    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '티 안 나게 잘 숨기고 있다고 생각했거든요'라고 말하며, 진짜 감정이나 약점을 들키는 것을 끔찍하게 여기는 태도가 드러남. 상담사가 괜찮은 척이 티가 나면 어떤 일이 생길 것 같은지 물은 것이 이 태도의 기반을 탐색하는 것임."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '가까워지면 제가 먼저 밀어냈거든요'라고 한 것이 이 전략(상대가 먼저 떠나기 전에 스스로 거리를 둠)과 정확히 일치함. 상담사가 '같은 결'이라고 연결한 대상이 바로 이 전략임."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/childhood_data", "/situations/1"],
      "relevance": "내담자가 '괜찮은 척하는 게 티가 난 건 아닐까'라고 말하며, 힘든 감정을 혼자 삭이고 괜찮은 모습만 유지하려는 전략이 현재 상담에서 직접 언급됨. 이 전략이 실패할 것 같다는 불안이 밀어내기 행동의 선행 조건임."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '가까워지면 먼저 밀어냈다'고 한 것이 이 전략(관계가 가까워지면 만남 자체를 줄임)과 대응함. 연인 관계에서 '무슨 생각을 하는지 모르겠다'는 말 이후 더 거리를 두는 패턴과 일치함."
    }
  ]
}

